// Scroll-driven motion for the OpenIPTV site. Each [data-progress] section
// gets --p: 0 when it enters at the bottom of the viewport, 1 when it leaves
// at the top. CSS turns that into transforms; nothing here animates by itself.
(() => {
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Screenshots are generated by CI; locally they may not exist yet.
  document.querySelectorAll('.tv__screen img, .phone__screen img').forEach((img) => {
    img.addEventListener('error', () => img.classList.add('is-missing'), { once: true });
  });

  document.querySelectorAll('[data-year]').forEach((el) => { el.textContent = new Date().getFullYear(); });

  // Split the statement into words, each with its own threshold (--k).
  document.querySelectorAll('[data-words]').forEach((el) => {
    const words = el.textContent.trim().split(/\s+/);
    el.textContent = '';
    words.forEach((word, i) => {
      const span = document.createElement('span');
      span.className = 'w';
      span.style.setProperty('--k', (i / words.length).toFixed(3));
      span.textContent = word;
      el.append(span, ' ');
    });
  });

  const nav = document.querySelector('[data-nav]');
  const light = document.querySelector('.features');
  const NAV_HEIGHT = 52;
  const tracked = [...document.querySelectorAll('[data-progress]')];
  const story = document.querySelector('[data-story]');
  const steps = story ? [...story.querySelectorAll('[data-step]')] : [];
  const shots = story ? [...story.querySelectorAll('[data-shot]')] : [];
  const dots = story ? [...story.querySelectorAll('.story__dots li')] : [];
  let current = 0;

  const clamp = (v) => Math.min(1, Math.max(0, v));

  function showStep(index) {
    if (index === current) return;
    current = index;
    steps.forEach((s, i) => s.classList.toggle('is-active', i === index));
    shots.forEach((s, i) => s.classList.toggle('is-active', i === index));
    dots.forEach((d, i) => d.classList.toggle('is-active', i === index));
  }

  function frame() {
    const vh = window.innerHeight;
    nav.classList.toggle('is-scrolled', window.scrollY > 8);
    // Over the light section the bar turns light, like the page under it.
    if (light) {
      const r = light.getBoundingClientRect();
      nav.classList.toggle('is-light', r.top <= NAV_HEIGHT && r.bottom > NAV_HEIGHT / 2);
    }

    if (!reduced) {
      tracked.forEach((el) => {
        const r = el.getBoundingClientRect();
        el.style.setProperty('--p', clamp((vh - r.top) / (vh + r.height)).toFixed(4));
      });
    }

    if (story && getComputedStyle(story).height !== 'auto') {
      const r = story.getBoundingClientRect();
      const travel = r.height - vh;
      if (travel > 0) {
        const p = clamp(-r.top / travel);
        showStep(Math.min(steps.length - 1, Math.floor(p * steps.length)));
      }
    }
  }

  let queued = false;
  const request = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; frame(); });
  };
  window.addEventListener('scroll', request, { passive: true });
  window.addEventListener('resize', request);
  frame();

  // One-time reveals as sections come into view.
  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-in');
        io.unobserve(entry.target);
      }
    });
  }, { rootMargin: '0px 0px -12% 0px' });
  document.querySelectorAll('.reveal').forEach((el) => io.observe(el));
})();
